/*
 * kernel.c — runs the recompiled arcade process: an emulated Linux i386
 * "kernel" for code generated by tools/recomp/lift.py.
 *
 * Like execve: maps the game and the (lifted) dynamic linker ld.so into
 * the guest address space, builds the initial stack (argv, envp, auxv with
 * AT_SYSINFO pointing at the syscall entry), and enters ld.so. ld.so then
 * loads the lifted libraries through the emulated open/mmap2, which places
 * each library at its arcade base (the addresses the code was lifted at
 * and the dump's GOT was frozen with).
 *
 * Host side (this file + syscalls.c): Windows x64 for development; the
 * guest address space is a 4 GB reservation at RT_MEM.
 *
 *   jp2015 [-v] <game dir> [game args...]
 *   env: JPRT_LIBDIR (dir with the i386 libs, default ext/debs layout),
 *        JPRT_LOG (log file, default jprt.log)
 */
#include <stdio.h>
#if defined(__ANDROID__)
#include <android/log.h>
#endif
#include <stdlib.h>
#include <string.h>
#include "rt.h"
#include "kernel.h"
#include "plat.h"

uint8_t *RT_MEM;

extern const struct { uint32_t addr; void (*fn)(rt_cpu *); } rt_func_table[];
extern const unsigned rt_func_count;
extern const struct { uint32_t addr; void (*fn)(rt_cpu *); } rt_resume_table[];
extern const unsigned rt_resume_count;
extern const struct { uint32_t addr; const char *name; } rt_thunk_table[];

/* ---- logging ---- */
static FILE *g_log;
int g_verbose;
static plat_mutex g_log_cs;

void klog(const char *fmt, ...)
{
    va_list ap;
    plat_mutex_lock(&g_log_cs);
    va_start(ap, fmt);
    if (g_log) { vfprintf(g_log, fmt, ap); fflush(g_log); }
    va_end(ap);
#if defined(__ANDROID__)
    va_start(ap, fmt);
    __android_log_vprint(4 /* ANDROID_LOG_INFO */, "jprt", fmt, ap);
    va_end(ap);
#endif
    if (g_verbose) {
        va_start(ap, fmt);
        vfprintf(stderr, fmt, ap);
        va_end(ap);
    }
    plat_mutex_unlock(&g_log_cs);
}

void kfatal(rt_cpu *cpu, const char *fmt, ...)
{
    va_list ap;
    char buf[512];
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    klog("FATAL: %s\n", buf);
    fprintf(stderr, "FATAL: %s\n", buf);
    if (cpu) {
        uint32_t i;
        klog("  eax=%08x ecx=%08x edx=%08x ebx=%08x esp=%08x ebp=%08x esi=%08x edi=%08x\n",
             cpu->eax, cpu->ecx, cpu->edx, cpu->ebx, cpu->esp, cpu->ebp, cpu->esi, cpu->edi);
        klog("  stack:");
        for (i = 0; i < 16 && mem_ok(cpu->esp + 4 * i, 4); i++)
            klog(" %08x", rd32(cpu->esp + 4 * i));
        klog("\n");
    }
    if (getenv("JPRT_PEEK")) {                 /* debugging: dump guest memory around an address */
        uint32_t p = (uint32_t)strtoul(getenv("JPRT_PEEK"), NULL, 16) & ~15u, j;
        for (j = 0; j < 8; j++) {
            uint32_t a = p - 0x40 + 16 * j, k;
            klog("  %08x:", a);
            for (k = 0; k < 4; k++)
                if (mem_ok(a + 4 * k, 4)) klog(" %08x", rd32(a + 4 * k)); else klog(" --------");
            klog("\n");
        }
    }
    exit(70);
}

/* ---- guest memory ---- */
#define NPAGES (1u << 20)
static uint8_t g_page[NPAGES];          /* 1 = mapped */
static plat_mutex g_mem_cs;

int mem_ok(uint32_t a, uint32_t len)
{
    uint32_t p;
    if (!len) return 1;
    for (p = a >> 12; p <= (uint32_t)((uint64_t)a + len - 1) >> 12; p++)
        if (!g_page[p]) return 0;
    return 1;
}

/* No page of [a, a+len) is mapped. */
int mem_free(uint32_t a, uint32_t len)
{
    uint32_t p;
    if (!len) return 1;
    if ((uint64_t)a + len > (1ull << 32)) return 0;
    for (p = a >> 12; p <= (uint32_t)((uint64_t)a + len - 1) >> 12; p++)
        if (g_page[p]) return 0;
    return 1;
}

/* Map [a, a+len) (page-rounded) as fresh zeroed memory. */
int mem_map(uint32_t a, uint32_t len)
{
    if (g_verbose && len >= 0x10000) klog("mem_map(%08x, %#x)\n", a, len);
    uint32_t lo = a & ~0xfffu, hi = (uint32_t)(((uint64_t)a + len + 0xfff) & ~0xfffull), p;
    if (hi <= lo) return -1;
    plat_mutex_lock(&g_mem_cs);
    if (plat_commit(RT_MEM + lo, hi - lo) < 0) {
        plat_mutex_unlock(&g_mem_cs);
        return -1;
    }
    for (p = lo >> 12; p < hi >> 12; p++) {
        if (g_page[p]) memset(RT_MEM + ((uint64_t)p << 12), 0, 4096);
        g_page[p] = 1;
    }
    plat_mutex_unlock(&g_mem_cs);
    return 0;
}

void mem_unmap(uint32_t a, uint32_t len)
{
    uint32_t p, lo = a & ~0xfffu, hi = (uint32_t)(((uint64_t)a + len + 0xfff) >> 12);
    plat_mutex_lock(&g_mem_cs);
    for (p = lo >> 12; p < hi; p++)
        g_page[p] = 0;
    /* decommit: a later mmap must see zero pages, as on Linux (glibc relies
     * on it, e.g. prev_size of mmapped malloc chunks) */
    if (hi > (lo >> 12))
        plat_decommit(RT_MEM + lo, ((uint64_t)hi << 12) - lo);
    plat_mutex_unlock(&g_mem_cs);
}

/* Highest free run of len bytes below top (top-down like Linux mmap). */
uint32_t mem_find(uint32_t len, uint32_t top)
{
    uint32_t n = (len + 0xfff) >> 12, run = 0, p;
    plat_mutex_lock(&g_mem_cs);
    for (p = top >> 12; p > 0x100; p--) {
        if (g_page[p - 1]) { run = 0; continue; }
        if (++run == n) { plat_mutex_unlock(&g_mem_cs); return (p - 1) << 12; }
    }
    plat_mutex_unlock(&g_mem_cs);
    return 0;
}

/* ---- ELF loading ---- */
static uint8_t *read_file(const char *path, size_t *size)
{
    FILE *f = fopen(path, "rb");
    uint8_t *b;
    long n;
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    n = ftell(f);
    fseek(f, 0, SEEK_SET);
    b = malloc(n);
    if (fread(b, 1, n, f) != (size_t)n) { free(b); fclose(f); return NULL; }
    fclose(f);
    *size = n;
    return b;
}

typedef struct { uint32_t entry, phdr, phnum, end; uint32_t dyn; } elf_info;

static int load_elf(const char *path, uint32_t base, elf_info *info)
{
    size_t sz;
    uint8_t *d = read_file(path, &sz);
    uint32_t phoff, i;
    uint16_t phnum;
    if (!d) return -1;
    memcpy(&phoff, d + 28, 4);
    memcpy(&phnum, d + 44, 2);
    memcpy(&info->entry, d + 24, 4);
    info->entry += base;
    info->phnum = phnum;
    info->end = 0;
    info->phdr = 0;
    info->dyn = 0;
    for (i = 0; i < phnum; i++) {
        uint32_t ph[8];
        memcpy(ph, d + phoff + 32 * i, 32);
        if (ph[0] == 1) {
            uint32_t va = base + ph[2];
            if (mem_map(va, ph[5]) < 0) return -2;
            memcpy(RT_MEM + va, d + ph[1], ph[4]);
            if (ph[1] <= phoff && phoff < ph[1] + ph[4])
                info->phdr = va + (phoff - ph[1]);
            if (va + ph[5] > info->end) info->end = va + ph[5];
        } else if (ph[0] == 2) {
            info->dyn = base + ph[2];
        }
    }
    free(d);
    return 0;
}

/* Libraries replaced by host code: drop them from the game's DT_NEEDED so
 * ld.so does not look for them (their functions are reached through the
 * dump's frozen GOT entries and dlopen/dlsym, both handled as thunks). */
static const char *const REPLACED[] = {
    "libSDL-1.2.so.0", "libGL.so.1",
    "libGLU.so.1", "libglut.so.3", "libudev.so.1", "libX11.so.6", NULL
};

int is_replaced_lib(const char *name)
{
    const char *base = strrchr(name, '/');
    int i;
    base = base ? base + 1 : name;
    for (i = 0; REPLACED[i]; i++)
        if (!strcmp(base, REPLACED[i]))
            return 1;
    return 0;
}

static void drop_replaced_needed(uint32_t dyn)
{
    uint32_t strtab = 0, d, verneed = 0, verneed_d = 0, num_d = 0;
    for (d = dyn; rd32(d); d += 8) {
        if (rd32(d) == 5) strtab = rd32(d + 4);
        if (rd32(d) == 0x6ffffffeu) { verneed = rd32(d + 4); verneed_d = d; }
        if (rd32(d) == 0x6fffffffu) num_d = d;
    }
    /* version requirements (DT_VERNEED) naming a replaced library: unlink
     * them, or ld.so asserts that the library is not loaded */
    if (verneed && num_d) {
        uint32_t cur = verneed, prev = 0, n = rd32(num_d + 4), i, kept = 0;
        for (i = 0; i < n && cur; i++) {
            uint32_t next = rd32(cur + 12);
            const char *file = (const char *)(RT_MEM + strtab + rd32(cur + 4));
            if (is_replaced_lib(file)) {
                klog("loader: dropping version requirements on %s\n", file);
                if (prev) wr32(prev + 12, next ? rd32(prev + 12) + next : 0);
                else { verneed = next ? cur + next : 0; wr32(verneed_d + 4, verneed); }
            } else {
                prev = cur;
                kept++;
            }
            cur = next ? cur + next : 0;
        }
        wr32(num_d + 4, kept);
        if (!kept) wr32(verneed_d, 0x6ffffd00u);
    }
    for (d = dyn; rd32(d); d += 8) {
        if (rd32(d) == 1) {
            const char *name = (const char *)(RT_MEM + strtab + rd32(d + 4));
            if (is_replaced_lib(name)) {
                klog("loader: dropping DT_NEEDED %s (host replacement)\n", name);
                wr32(d, 0x6ffffd00u);          /* tag ld.so ignores */
            }
        }
    }
}

/* Game relocations whose symbols live only in replaced libraries
 * (tools/recomp: listed by comparing the game's relocations with the lifted
 * libraries' exports). ld.so would fail on them with LD_BIND_NOW, so they
 * are neutralized: JMP_SLOTs get host thunk addresses, the COPY of the
 * glut font object stays the game's own zeroed copy (its address is the
 * font handle the host glut recognizes). */
static const char *const HOST_RELOC_SYMS[] = {
    "glutBitmap8By13", "XOpenDisplay", "XCloseDisplay", "XFlush", "XGetWindowAttributes", NULL
};

static void neutralize_host_relocs(uint32_t dyn)
{
    uint32_t symtab = 0, strtab = 0, tabs[2][2] = { { 0, 0 }, { 0, 0 } }, d, t, r;
    for (d = dyn; rd32(d); d += 8) {
        switch (rd32(d)) {
        case 5: strtab = rd32(d + 4); break;
        case 6: symtab = rd32(d + 4); break;
        case 17: tabs[0][0] = rd32(d + 4); break;        /* DT_REL */
        case 18: tabs[0][1] = rd32(d + 4); break;
        case 23: tabs[1][0] = rd32(d + 4); break;        /* DT_JMPREL */
        case 2: tabs[1][1] = rd32(d + 4); break;
        }
    }
    for (t = 0; t < 2; t++) {
        for (r = tabs[t][0]; r && r < tabs[t][0] + tabs[t][1]; r += 8) {
            uint32_t off = rd32(r), info = rd32(r + 4), sym = info >> 8, i;
            const char *name;
            if (!sym) continue;
            name = (const char *)(RT_MEM + strtab + rd32(symtab + 16 * sym));
            for (i = 0; HOST_RELOC_SYMS[i]; i++) {
                if (strcmp(name, HOST_RELOC_SYMS[i])) continue;
                if ((info & 0xff) == 7) wr32(off, host_thunk_addr(name));
                klog("loader: relocation %u for %s at %08x handled by the host\n", info & 0xff, name, off);
                wr32(r + 4, info & ~0xffu);            /* R_386_NONE */
            }
        }
    }
}

/* ---- function lookup / dispatch ---- */
typedef void (*lifted_fn)(rt_cpu *);

/* Both lookups below run on every indirect call and every call into a
 * replaced library (each GL call): a direct-mapped cache in front of the
 * binary search, and a hash of the (fixed) thunk table instead of a scan. */
#define FL_BITS 16
static uint64_t g_fl_cache[1u << FL_BITS];   /* addr << 32 | (table index + 1) */

lifted_fn find_lifted(uint32_t a)
{
    uint32_t h = (a * 2654435761u) >> (32 - FL_BITS);
    uint64_t e = __atomic_load_n(&g_fl_cache[h], __ATOMIC_RELAXED);
    unsigned lo = 0, hi = rt_func_count;
    if ((uint32_t)(e >> 32) == a && (uint32_t)e) return rt_func_table[(uint32_t)e - 1].fn;
    while (lo < hi) {
        unsigned mid = (lo + hi) / 2;
        if (rt_func_table[mid].addr < a) lo = mid + 1; else hi = mid;
    }
    if (lo < rt_func_count && rt_func_table[lo].addr == a) {
        __atomic_store_n(&g_fl_cache[h], (uint64_t)a << 32 | (lo + 1), __ATOMIC_RELAXED);
        return rt_func_table[lo].fn;
    }
    return NULL;
}

lifted_fn find_resume(uint32_t a)
{
    unsigned lo = 0, hi = rt_resume_count;            /* sorted by address */
    while (lo < hi) {
        unsigned mid = (lo + hi) / 2;
        if (rt_resume_table[mid].addr < a) lo = mid + 1; else hi = mid;
    }
    return (lo < rt_resume_count && rt_resume_table[lo].addr == a) ? rt_resume_table[lo].fn : NULL;
}

#define TH_BITS 16
static int32_t g_th_hash[1u << TH_BITS];     /* thunk table index + 1; 0 = empty */
static int g_th_state;                        /* 0 none, 1 building, 2 ready */

static uint32_t th_slot(uint32_t a) { return (a * 2654435761u) >> (32 - TH_BITS); }

static void th_build(void)
{
    int expect = 0;
    if (__atomic_compare_exchange_n(&g_th_state, &expect, 1, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
        unsigned i, n = 0;
        for (i = 0; rt_thunk_table[i].name; i++) {
            uint32_t s = th_slot(rt_thunk_table[i].addr);
            if (++n >= (1u << TH_BITS) / 2) kfatal(NULL, "thunk table too large for its hash");
            while (g_th_hash[s] && rt_thunk_table[g_th_hash[s] - 1].addr != rt_thunk_table[i].addr)
                s = (s + 1) & ((1u << TH_BITS) - 1);
            if (!g_th_hash[s]) g_th_hash[s] = (int32_t)i + 1;   /* first entry wins, as the scan did */
        }
        __atomic_store_n(&g_th_state, 2, __ATOMIC_RELEASE);
    }
    while (__atomic_load_n(&g_th_state, __ATOMIC_ACQUIRE) != 2) plat_yield();
}

const char *thunk_name(uint32_t a)
{
    uint32_t s;
    if (__atomic_load_n(&g_th_state, __ATOMIC_ACQUIRE) != 2) th_build();
    for (s = th_slot(a); g_th_hash[s]; s = (s + 1) & ((1u << TH_BITS) - 1))
        if (rt_thunk_table[g_th_hash[s] - 1].addr == a) return rt_thunk_table[g_th_hash[s] - 1].name;
    return dyn_thunk_name(a);
}

void rt_call(rt_cpu *cpu, uint32_t target)
{
    lifted_fn fn;
    if (target == SYSCALL_ENTRY) {           /* call *%gs:0x10 (AT_SYSINFO) */
        rt_syscall(cpu, 0);
        cpu->esp += 4;                       /* ret */
        return;
    }
    if (host_call(cpu, target))              /* overrides and replaced-library thunks */
        return;
    fn = find_lifted(target);
    if (fn) {
        fn(cpu);
        return;
    }
    /* a jump to a call-return site / landing pad (longjmp's `jmp *edx`,
     * coroutine switches): continue there from the trampoline */
    if (find_resume(target))
        rt_bounce(cpu, target);
    /* address of a PLT stub (`jmp dword ptr [slot]`), e.g. a library
     * function's address taken by the game: follow the GOT slot */
    if (mem_ok(target, 6) && rd8(target) == 0xff && rd8(target + 1) == 0x25) {
        rt_call(cpu, rd32(rd32(target + 2)));
        return;
    }
    kfatal(cpu, "call to %08x: no lifted function there (%s)", target,
           thunk_name(target) ? thunk_name(target) : "unknown");
}

void rt_import(rt_cpu *cpu, int id)
{
    kfatal(cpu, "rt_import(%d): not used in the full-process build", id);
}

void rt_unimpl(rt_cpu *cpu, uint32_t addr, const char *what)
{
    kfatal(cpu, "unlifted instruction at %08x: %s", addr, what);
}

void rt_trap(rt_cpu *cpu, uint32_t addr, const char *what)
{
    kfatal(cpu, "trap at %08x: %s", addr, what);
}

void rt_cpuid(rt_cpu *cpu)
{
    /* Present the arcade-class CPU: SSE..SSE4.2, no AVX/TSX/RDRAND, so the
     * libraries' runtime CPU dispatch stays on lifted code paths. */
    uint32_t leaf = cpu->eax;
    uint32_t a = 0, b = 0, c = 0, d = 0;
    if (leaf == 0) {
        a = 0xb; b = 0x756e6547; d = 0x49656e69; c = 0x6c65746e;      /* GenuineIntel */
    } else if (leaf == 1) {
        a = 0x000206a7;                                                  /* family 6 */
        b = 0x00010800;
        c = (1u << 0) | (1u << 9) | (1u << 13) | (1u << 19) | (1u << 20) | (1u << 23); /* sse3 ssse3 cx16 sse4.1 sse4.2 popcnt */
        d = 0x0f8bfbffu & ~(1u << 28);                                   /* fpu..sse2, no HTT */
    }
    cpu->eax = a; cpu->ebx = b; cpu->ecx = c; cpu->edx = d;
}

uint64_t rt_rdtsc(void)
{
    return plat_mono_ns();
}

/* ---- initial stack (System V i386 ABI, like Linux execve) ---- */
#define STACK_TOP  0xbf800000u
#define STACK_SIZE 0x00800000u

static uint32_t push_str(uint32_t *sp, const char *s)
{
    uint32_t n = (uint32_t)strlen(s) + 1;
    *sp -= n;
    memcpy(RT_MEM + *sp, s, n);
    return *sp;
}

static uint32_t build_stack(int argc, char **argv, char **envp, const elf_info *game, uint32_t ld_base)
{
    uint32_t sp = STACK_TOP, argvp[64], envpp[64], rnd, plat, i, n_env = 0;
    mem_map(STACK_TOP - STACK_SIZE, STACK_SIZE);
    plat = push_str(&sp, "i686");
    sp -= 16;
    rnd = sp;
    for (i = 0; i < 16; i++) RT_MEM[rnd + i] = (uint8_t)(rand() ^ (i * 37));
    for (i = 0; envp[i] && i < 63; i++) envpp[n_env++] = push_str(&sp, envp[i]);
    for (i = 0; i < (uint32_t)argc && i < 63; i++) argvp[i] = push_str(&sp, argv[i]);
    sp &= ~15u;
    {
        uint32_t aux[][2] = {
            { 3, game->phdr }, { 4, 32 }, { 5, game->phnum }, { 6, 4096 }, { 7, ld_base },
            { 8, 0 }, { 9, game->entry }, { 11, 0 }, { 12, 0 }, { 13, 0 }, { 14, 0 },
            { 16, 0xbfebfbffu }, { 17, 100 }, { 15, plat }, { 23, 0 }, { 25, rnd },
            { 32, SYSCALL_ENTRY }, { 0, 0 }
        };
        uint32_t words = 1 + argc + 1 + n_env + 1 + 2 * (sizeof(aux) / 8);
        sp -= words * 4;
        sp &= ~15u;
        {
            uint32_t p = sp;
            wr32(p, (uint32_t)argc); p += 4;
            for (i = 0; i < (uint32_t)argc; i++, p += 4) wr32(p, argvp[i]);
            wr32(p, 0); p += 4;
            for (i = 0; i < n_env; i++, p += 4) wr32(p, envpp[i]);
            wr32(p, 0); p += 4;
            for (i = 0; i < sizeof(aux) / 8; i++, p += 8) { wr32(p, aux[i][0]); wr32(p + 4, aux[i][1]); }
        }
    }
    return sp;
}

uint32_t g_brk_start, g_brk;

/* Host exceptions (an access to unmapped guest memory shows up as an access
 * violation inside the 4 GB reservation): report the guest address. */
static void bt_line(const char *l) { klog("%s", l); }
static void host_backtrace(void) { plat_backtrace(bt_line); }

/* Debug write watchpoint (JPRT_WATCH=<guest addr>): the page is read-only;
 * each write faults, is logged with its host pc (symbolize.py maps it to the
 * guest instruction), then single-stepped with the page writable. */
static uint32_t g_watch, g_watch_page;
static int32_t g_watch_hits;

static int g_watch_armed;

static void watch_arm(void)
{
    plat_protect(RT_MEM + g_watch_page, 4096, 0);
}

/* called on every syscall: arm the watchpoint once its page is mapped */
void watch_poll(void)
{
    if (g_watch && mem_ok(g_watch_page, 4096)) {
        if (!g_watch_armed) klog("watchpoint armed: %08x = %08x\n", g_watch, rd32(g_watch));
        g_watch_armed = 1;
        watch_arm();          /* re-arm: a MAP_FIXED remap resets page protection */
    }
}

static int host_fault(int kind, uintptr_t a, int write, void *pc)
{
    uintptr_t base = (uintptr_t)RT_MEM;
    if (g_watch) {
        if (kind == PLAT_FAULT_ACCESS && write && a >= base + g_watch_page && a < base + g_watch_page + 4096u) {
            uint32_t ga = (uint32_t)(a - base);
            if (ga >= g_watch && ga < g_watch + 4u && plat_atomic_inc(&g_watch_hits) < 64) {
                klog("WATCH write to %08x (value before %08x) at host pc %p\n", ga, rd32(g_watch), pc);
                host_backtrace();
            }
            plat_protect(RT_MEM + g_watch_page, 4096, 1);
            return 2;                                    /* single-step the write, then re-arm */
        }
        if (kind == PLAT_FAULT_STEP && g_watch_armed) {
            watch_arm();
            return 1;
        }
    }
    if (kind == PLAT_FAULT_ACCESS || kind == PLAT_FAULT_STACK)
        host_backtrace();
    if (kind == PLAT_FAULT_ACCESS) {
        if (a >= base && a < base + (1ull << 32))
            kfatal(current_cpu(), "guest %s of unmapped address %08x (host pc %p)",
                   write ? "write" : "access", (uint32_t)(a - base), pc);
        kfatal(current_cpu(), "host access violation at %p (address %p)", pc, (void *)a);
    }
    if (kind == PLAT_FAULT_STACK)
        kfatal(NULL, "host stack overflow (runaway guest recursion?)");
    if (kind == PLAT_FAULT_DIV0)
        kfatal(NULL, "host divide by zero at %p", pc);
    if (kind == PLAT_FAULT_OTHER)
        kfatal(current_cpu(), "host fault (illegal instruction?) at %p", pc);
    return 0;
}

int jprt_main(int argc, char **argv)
{
    int ai = 1;
    elf_info game, ld;
    char path[1024];
    rt_cpu *cpu;

    plat_mutex_init(&g_log_cs);
    plat_mutex_init(&g_mem_cs);
    plat_install_fault_handler(host_fault);
    plat_guest_thread_init();
    if (ai < argc && !strcmp(argv[ai], "-v")) { g_verbose = 1; ai++; }
    if (ai >= argc) {
        fprintf(stderr, "usage: %s [-v] <game dir> [game args...]\n", argv[0]);
        return 2;
    }
    g_log = fopen(getenv("JPRT_LOG") ? getenv("JPRT_LOG") : "jprt.log", "w");
    vfs_init(argv[ai]);

    RT_MEM = plat_reserve(1ull << 32);
    if (!RT_MEM) { fprintf(stderr, "cannot reserve 4 GB guest space\n"); return 1; }
    klog("guest memory at %p\n", RT_MEM);
    host_heap_init();

    snprintf(path, sizeof(path), "%s/game", argv[ai]);
    if (load_elf(path, 0, &game) < 0) kfatal(NULL, "cannot load %s", path);
    if (!vfs_host_path("/lib/ld-linux.so.2", path, sizeof(path)) || load_elf(path, LD_BASE, &ld) < 0)
        kfatal(NULL, "cannot load ld.so (%s)", path);
    klog("game: entry %08x phdr %08x end %08x; ld.so at %08x entry %08x\n",
         game.entry, game.phdr, game.end, LD_BASE, ld.entry);
    drop_replaced_needed(game.dyn);
    neutralize_host_relocs(game.dyn);
    g_brk_start = g_brk = (game.end + 0xfff) & ~0xfffu;

    {
        char *gargv[64];
        char *envp[] = { "LD_BIND_NOW=1", "HOME=/root", "PATH=/usr/bin:/bin", "LANG=C",
                         "USER=root", "DISPLAY=:0", "SDL_AUDIODRIVER=dummy", NULL };
        int n = 0, i;
        gargv[n++] = "/pm/game";
        for (i = ai + 1; i < argc && n < 63; i++) gargv[n++] = argv[i];
        if (n == 1) { gargv[n++] = "-n"; }
        cpu = thread_new_cpu();
        cpu->esp = build_stack(n, gargv, envp, &game, LD_BASE);
    }
    cpu->fpucw = 0x37f;
    cpu->mxcsr = 0x1f80;
    klog("entering ld.so at %08x, esp %08x\n", ld.entry, cpu->esp);
    if (getenv("JPRT_WATCH")) {
        g_watch = (uint32_t)strtoul(getenv("JPRT_WATCH"), NULL, 16);
        g_watch_page = g_watch & ~0xfffu;
        klog("watching writes to %08x\n", g_watch);
    }
    run_guest(cpu, ld.entry, 0);
    return 0;
}

#if !defined(JPRT_NO_MAIN) && !defined(__ANDROID__)
int main(int argc, char **argv) { return jprt_main(argc, argv); }
#endif
